int vc4_get_cmdlist_and_shader_recs(struct drm_device *dev, struct vc4_exec_info *exec)
{
    struct vc4_dev *vc4_dev = to_vc4_dev(dev);
    struct vc4_bo *bo;
    void *cmdlist, *shader_recs;
    int ret;

    if (exec->cmdlist_size == 0 || exec->shader_recs_size == 0) {
        return -EINVAL;
    }

    cmdlist = kmalloc(exec->cmdlist_size, GFP_KERNEL);
    if (!cmdlist) {
        return -ENOMEM;
    }

    shader_recs = kmalloc(exec->shader_recs_size, GFP_KERNEL);
    if (!shader_recs) {
        kfree(cmdlist);
        return -ENOMEM;
    }

    if (copy_from_user(cmdlist, u64_to_user_ptr(exec->cmdlist_ptr), exec->cmdlist_size) ||
        copy_from_user(shader_recs, u64_to_user_ptr(exec->shader_recs_ptr), exec->shader_recs_size)) {
        kfree(cmdlist);
        kfree(shader_recs);
        return -EFAULT;
    }

    ret = vc4_validate_cmdlist(cmdlist, exec->cmdlist_size);
    if (ret) {
        kfree(cmdlist);
        kfree(shader_recs);
        return ret;
    }

    ret = vc4_validate_shader_recs(shader_recs, exec->shader_recs_size);
    if (ret) {
        kfree(cmdlist);
        kfree(shader_recs);
        return ret;
    }

    bo = vc4_bo_create(dev, exec->cmdlist_size + exec->shader_recs_size, true);
    if (IS_ERR(bo)) {
        kfree(cmdlist);
        kfree(shader_recs);
        return PTR_ERR(bo);
    }

    exec->cmdlist_bo = bo;
    exec->cmdlist = cmdlist;
    exec->shader_recs = shader_recs;

    ret = vc4_flush_prev_submissions(dev);
    if (ret) {
        kfree(cmdlist);
        kfree(shader_recs);
        return ret;
    }

    return 0;
}

int vc4_prepare_cmdlists_and_shaders(struct drm_device *dev, struct vc4_exec_info *exec)
{
    void *cmdlist, *shader_records;
    int ret;

    if (!exec->cmdlist_size || !exec->shader_record_size)
        return -EINVAL;

    cmdlist = kzalloc(exec->cmdlist_size, GFP_KERNEL);
    if (!cmdlist)
        return -ENOMEM;

    shader_records = kzalloc(exec->shader_record_size, GFP_KERNEL);
    if (!shader_records) {
        ret = -ENOMEM;
        goto free_cmdlist;
    }

    if (copy_from_user(cmdlist, u64_to_user_ptr(exec->cmdlist), exec->cmdlist_size)) {
        ret = -EFAULT;
        goto free_shader_records;
    }

    if (copy_from_user(shader_records, u64_to_user_ptr(exec->shader_records), exec->shader_record_size)) {
        ret = -EFAULT;
        goto free_shader_records;
    }

    exec->cmdlist = cmdlist;
    exec->shader_records = shader_records;

    ret = vc4_create_bo(dev, exec->cmdlist_size + exec->shader_record_size, &exec->exec_bo);
    if (ret)
        goto cleanup;

    /* Setup pointers to shader records and uniforms (simplified) */
    exec->shader_record_ptr = exec->cmdlist + exec->cmdlist_size;
    exec->uniform_ptr = exec->shader_record_ptr + exec->shader_record_size;

    ret = vc4_validate_cmdlist(cmdlist, exec->cmdlist_size);
    if (ret)
        goto cleanup;

    ret = vc4_validate_shader_records(shader_records, exec->shader_record_size);
    if (ret)
        goto cleanup;

    vc4_wait_for_render_completion(dev);

    return 0;

cleanup:
    kfree(shader_records);
    kfree(cmdlist);
    return ret;

free_shader_records:
    kfree(shader_records);
free_cmdlist:
    kfree(cmdlist);
    return ret;
}

int vc4_prepare_exec(struct drm_device *dev, struct vc4_exec_info *exec)
{
    int ret;
    unsigned int i;

    ret = vc4_validate_cmd_lists(exec);
    if (ret)
        return ret;

    exec->cmd_list = kzalloc(exec->cmd_list_size, GFP_KERNEL);
    if (!exec->cmd_list)
        return -ENOMEM;

    if (copy_from_user(exec->cmd_list, u64_to_user_ptr(exec->cmd_list_ptr),
                         exec->cmd_list_size)) {
        kfree(exec->cmd_list);
        return -EFAULT;
    }

    ret = vc4_validate_shader_records(exec);
    if (ret)
        return ret;

    exec->shader_records = kzalloc(exec->shader_record_size, GFP_KERNEL);
    if (!exec->shader_records) {
        kfree(exec->cmd_list);
        return -ENOMEM;
    }

    if (copy_from_user(exec->shader_records,
                         u64_to_user_ptr(exec->shader_records_ptr),
                         exec->shader_record_size)) {
        kfree(exec->cmd_list);
        kfree(exec->shader_records);
        return -EFAULT;
    }

    exec->bo = drm_gem_cma_create(dev, exec->bo_size);
    if (!exec->bo) {
        kfree(exec->cmd_list);
        kfree(exec->shader_records);
        return -ENOMEM;
    }

    for (i = 0; i < exec->uniform_count; i++) {
        exec->uniforms[i].data = kzalloc(exec->uniforms[i].size, GFP_KERNEL);
        if (!exec->uniforms[i].data) {
            ret = -ENOMEM;
            break;
        }

        if (copy_from_user(exec->uniforms[i].data,
                             u64_to_user_ptr(exec->uniforms[i].user_ptr),
                             exec->uniforms[i].size)) {
            ret = -EFAULT;
            break;
        }
    }

    if (ret) {
        kfree(exec->cmd_list);
        kfree(exec->shader_records);
        drm_gem_object_put(exec->bo);
        return ret;
    }

    ret = vc4_validate_command_list(exec->cmd_list, exec->cmd_list_size);
    if (ret)
        return ret;

    ret = vc4_validate_shader_records(exec->shader_records,
                                        exec->shader_record_size);
    if (ret)
        return ret;

    if (exec->previous_bo)
        vc4_wait_for_previous_rendering(exec->previous_bo);

    return 0;
}

int vc4_prepare_cmdlist_and_shader_records(struct drm_device *dev, struct vc4_exec_info *exec) {
    struct vc4_dev *vc4 = to_vc4_dev(dev);
    struct vc4_bo *bo = NULL;
    void *cmdlist, *shader_records;
    int ret;

    if (!exec->args->cmdlist_size || !exec->args->shader_records_size)
        return -EINVAL;

    cmdlist = kcalloc(exec->args->cmdlist_size, sizeof(u32), GFP_KERNEL);
    if (!cmdlist)
        return -ENOMEM;

    shader_records = kcalloc(exec->args->shader_records_size, sizeof(u32), GFP_KERNEL);
    if (!shader_records) {
        kfree(cmdlist);
        return -ENOMEM;
    }

    if (copy_from_user(cmdlist, u64_to_user_ptr(exec->args->cmdlist), exec->args->cmdlist_size * sizeof(u32))) {
        ret = -EFAULT;
        goto fail;
    }

    if (copy_from_user(shader_records, u64_to_user_ptr(exec->args->shader_records), exec->args->shader_records_size * sizeof(u32))) {
        ret = -EFAULT;
        goto fail;
    }

    ret = vc4_bo_create(dev, exec->args->bo_size, 0, &bo);
    if (ret)
        goto fail;

    exec->bo = bo;
    exec->cmdlist = cmdlist;
    exec->shader_records = shader_records;

    if (!vc4_validate_cmdlist(cmdlist, exec->args->cmdlist_size)) {
        ret = -EINVAL;
        goto fail;
    }

    if (!vc4_validate_shader_records(shader_records, exec->args->shader_records_size)) {
        ret = -EINVAL;
        goto fail;
    }

    ret = vc4_wait_for_render_complete(dev);
    if (ret)
        goto fail;

    return 0;

fail:
    kfree(cmdlist);
    kfree(shader_records);
    if (bo)
        vc4_bo_unref(dev, bo);
    return ret;
}

